style.css:
@-moz-document domain("roblox.com") {
body {
    font-family: 'Baloo 2', cursive;
  }
  
  .roblox-font {
    font-family: 'Baloo 2', cursive;
    font-weight: 500;
    color: #ff63b2;
    background: linear-gradient(45deg, #ff79c6, #ffb3d9);
    -webkit-background-clip: text;
    background-clip: text;
    font-size: 3.5em;
    padding: 0 15px;
    border-radius: 20px;
    text-transform: uppercase;
    letter-spacing: 3px;
  }
}
